import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices finds single overdue invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].daysOverdue, 16);
  assert.equal(result[0].dueDate, '2026-09-21');
});

test('overdueInvoices includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([r.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = overdueInvoices([paid.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const result = overdueInvoices([withPayment.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 5000);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-23',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by most overdue first', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued2.value, issued1.value], '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 22);
  assert.equal(result[1].daysOverdue, 8);
});

test('overdueInvoices includes multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.length, 2);
});

test('overdueInvoices filters by status from mixed array', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const totals2 = invoiceTotals(issued2.value);
  const paid2 = recordPayment(issued2.value, { amount: totals2.total, date: '2026-10-08' });
  const result = overdueInvoices([issued1.value, r2.value, paid2.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices with EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'EOM',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2026-09-30');
});

test('overdueInvoices calculates due with partial payment', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const result = overdueInvoices([withPayment.value], '2026-10-07');
  assert.equal(result[0].due, totals.total - 5000);
});

test('overdueInvoices with different customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-07');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices returns correct shape', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  const inv = result[0];
  assert.ok('number' in inv);
  assert.ok('customerId' in inv);
  assert.ok('dueDate' in inv);
  assert.ok('daysOverdue' in inv);
  assert.ok('due' in inv);
  assert.equal(Object.keys(inv).length, 5);
});

test('overdueInvoices does not mutate input', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  overdueInvoices(invoices, '2026-10-07');
  assert.equal(invoices.length, 1);
  assert.equal(invoices[0].status, 'issued');
});

test('overdueInvoices with discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices orders correctly with equal daysOverdue', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, result[1].daysOverdue);
});

test('overdueInvoices with 1 day overdue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with 0 due amount (fully paid)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  paid.value.status = 'partially_paid';
  const result = overdueInvoices([paid.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 0);
});

test('overdueInvoices returns dueDate as string', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(typeof result[0].dueDate, 'string');
  assert.match(result[0].dueDate, /^\d{4}-\d{2}-\d{2}$/);
});

test('overdueInvoices returns daysOverdue as number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(typeof result[0].daysOverdue, 'number');
  assert.ok(Number.isInteger(result[0].daysOverdue));
});

test('overdueInvoices returns due as number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(typeof result[0].due, 'number');
  assert.ok(Number.isInteger(result[0].due));
});

test('overdueInvoices with multiple overdue at different stages', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-09-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const totals3 = invoiceTotals(issued3.value);
  const partial3 = recordPayment(issued3.value, { amount: 5000, date: '2026-10-08' });
  const result = overdueInvoices([issued1.value, issued2.value, partial3.value], '2026-10-07');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0002');
  assert.equal(result[2].number, 'INV-2026-0003');
  assert.ok(result[0].daysOverdue > result[1].daysOverdue);
  assert.ok(result[1].daysOverdue > result[2].daysOverdue);
});

